package dev.kelmagic.client;
import dev.kelmagic.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.GameRules;import net.minecraft.world.level.GameType;import net.minecraft.world.level.levelgen.Heightmap;import net.minecraft.world.level.levelgen.structure.templatesystem.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
/** Generates the disposable exhibition save only with explicit developer property. Excluded from release. */
@EventBusSubscriber(modid=KelMagic.MODID)public final class QaShowcase {
 static volatile boolean ready;static boolean building;
 static void label(net.minecraft.server.level.ServerLevel l,BlockPos at,String a,String b){l.setBlockAndUpdate(at,Blocks.OAK_SIGN.defaultBlockState().setValue(StandingSignBlock.ROTATION,8));if(l.getBlockEntity(at) instanceof SignBlockEntity sign){sign.setText(sign.getFrontText().setMessage(0,Component.literal(a)).setMessage(1,Component.literal(b)),true);sign.setWaxed(true);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.showcaseQA")||building||e.getServer().getPlayerList().getPlayers().isEmpty())return;building=true;var server=e.getServer();var l=server.overworld();int y=l.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,40,0)-1;
  l.setDayTime(1000);l.setWeatherParameters(600000,0,false,false);l.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,server);l.getGameRules().getRule(GameRules.RULE_WEATHER_CYCLE).set(false,server);l.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,server);l.getGameRules().getRule(GameRules.RULE_RANDOMTICKING).set(3,server);l.setDefaultSpawnPos(new BlockPos(42,y+1,-12),0);
  String[] biomes={"plains","desert","taiga","snowy","savanna"};String[] titles={"PLAINS","DESERT","TAIGA","SNOWY","SAVANNA"};
  for(int row=0;row<5;row++)for(int v=1;v<=3;v++){var at=new BlockPos((v-1)*40,y,row*40);var template=l.getStructureManager().get(ResourceLocation.fromNamespaceAndPath(KelMagic.MODID,"archive/"+biomes[row]+"_"+v)).orElseThrow();template.placeInWorld(l,at,at,new StructurePlaceSettings().addProcessor(JigsawReplacementProcessor.INSTANCE),l.random,Block.UPDATE_CLIENTS|Block.UPDATE_NEIGHBORS);for(int x=at.getX()-2;x<at.getX()+template.getSize().getX()+2;x++)for(int z=at.getZ()-5;z<at.getZ();z++)l.setBlockAndUpdate(new BlockPos(x,y,z),Blocks.STONE_BRICKS.defaultBlockState());label(l,at.offset(2,1,-3),titles[row],"Archive "+v);}
  // Paths join the five rows without changing any house.
  for(int z=-12;z<180;z++)for(int x=30;x<35;x++)l.setBlockAndUpdate(new BlockPos(x,y,z),Blocks.SMOOTH_STONE.defaultBlockState());
  label(l,new BlockPos(38,y+1,-8),"KelMagic 1.14.0","15 ARCHIVES");label(l,new BlockPos(128,y+1,-8),"COPPER GALLERY","74 WORDS / 4 AGES");
  for(int i=0;i<MagicCopper.WORDS.size();i++){String word=MagicCopper.WORDS.get(i);int z=i*4;for(int age=0;age<4;age++)for(boolean waxed:new boolean[]{false,true}){int x=140+age*4+(waxed?20:0);l.setBlockAndUpdate(new BlockPos(x,y,z),Blocks.SMOOTH_STONE.defaultBlockState());l.setBlockAndUpdate(new BlockPos(x,y+1,z),MagicCopper.block(word,age,waxed).defaultBlockState());}label(l,new BlockPos(136,y+1,z),word,"Raw / Waxed");}
  // Work bench for practical exploration: vanilla stock, cutter, axes, wax and example glyphs.
  l.setBlockAndUpdate(new BlockPos(45,y+1,-8),Blocks.STONECUTTER.defaultBlockState());l.setBlockAndUpdate(new BlockPos(47,y+1,-8),Blocks.CRAFTING_TABLE.defaultBlockState());var chestAt=new BlockPos(49,y+1,-8);l.setBlockAndUpdate(chestAt,Blocks.CHEST.defaultBlockState());if(l.getBlockEntity(chestAt) instanceof ChestBlockEntity chest){int slot=0;for(Item item:new Item[]{Items.COPPER_BLOCK,Items.EXPOSED_COPPER,Items.WEATHERED_COPPER,Items.OXIDIZED_COPPER,Items.HONEYCOMB,Items.IRON_AXE,Items.STONE_PICKAXE,Items.LIGHTNING_ROD})chest.setItem(slot++,new ItemStack(item,item==Items.IRON_AXE||item==Items.STONE_PICKAXE?1:64));chest.setItem(slot++,MagicCopper.ITEMS.get(MagicCopper.id("pir",0,false)).toStack());chest.setItem(slot,MagicArchive.CREATIVE_CODEX.toStack());chest.setChanged();}
  for(var p:server.getPlayerList().getPlayers()){p.setGameMode(GameType.CREATIVE);p.teleportTo(42,y+1,-12);p.setYRot(0);p.setXRot(0);p.getInventory().clearContent();p.getInventory().setChanged();}ready=true;System.out.println("SHOWCASE_114_READY:15 real NBT houses;592 copper exhibits;floorY="+y);}
 private QaShowcase(){}
}
